insert into public.subjects (id, code, slug, title, subtitle, theme, position, estimated_minutes, description, is_published)
values
  ('10000000-0000-4000-8000-000000000001', '01', 'medical-training', 'Медицинская подготовка', 'Первая помощь • профилактика', 'blue', 1, 228, 'Безопасная последовательность первой помощи, профилактика заболеваний и работа с индивидуальным оснащением.', true),
  ('10000000-0000-4000-8000-000000000002', '02', 'firearms-training', 'Огневая подготовка', 'Теория • безопасность', 'blue', 2, 150, 'Безопасность, устройство и порядок действий.', true),
  ('10000000-0000-4000-8000-000000000003', '03', 'rhb-protection', 'РХБ защита', 'Опасности • защита • контроль', 'olive', 3, 153, 'Распознавание РХБ-опасностей, средства защиты, контроль и специальная обработка.', true),
  ('10000000-0000-4000-8000-000000000004', '04', 'tactical-training', 'Тактическая подготовка', 'Теория • взаимодействие', 'olive', 4, 175, 'Наблюдение, передвижение и взаимодействие.', true),
  ('10000000-0000-4000-8000-000000000005', '05', 'military-topography', 'Военная топография', 'Карты • координаты • ориентирование', 'blue', 5, 220, 'Чтение топографической карты, системы координат, ориентирование, измерения и рабочая карта.', true),
  ('10000000-0000-4000-8000-000000000006', '06', 'engineering-training', 'Инженерная подготовка', 'Общие положения', 'blue', 6, 100, 'Общие положения и инженерные средства.', true),
  ('10000000-0000-4000-8000-000000000007', '07', 'military-regulations', 'Общевоинские уставы', 'Служба • дисциплина • порядок', 'olive', 7, 170, 'Общие обязанности, взаимоотношения, внутренний порядок, дисциплина и базовые уставные понятия.', true);
insert into public.modules (id, subject_id, title, position, is_published, summary, estimated_minutes, objective, key_principle, short_summary, learning_tip)
values
  ('21000000-0000-4000-8000-000000000001', '10000000-0000-4000-8000-000000000001', 'Личная гигиена и профилактика инфекций', 1, true, 'Теория + тест', 24, 'Понять, как разрывается цепочка передачи инфекции и какие ежедневные действия снижают риск заболевания.', 'Профилактика строится на чистоте, безопасном поведении и своевременном сообщении о признаках заболевания.', 'Источник → путь передачи → восприимчивый человек → разрыв цепочки.', 'Для каждого пути передачи назовите конкретную меру профилактики.'),
  ('21000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000000001', 'Безопасность питания и воды', 2, true, 'Теория + тест', 25, 'Различать безопасный источник воды, пункт водоснабжения и действия при сомнительном качестве пищи или воды.', 'Внешний вид воды и пищи не подтверждает их безопасность.', 'Проверенный источник → установленная обработка → чистое хранение → контроль состояния.', 'Не запоминайте устаревающие дозировки средств: ориентируйтесь на действующую инструкцию конкретного средства.'),
  ('21000000-0000-4000-8000-000000000003', '10000000-0000-4000-8000-000000000001', 'Индивидуальное медицинское оснащение', 3, true, 'Теория + тест', 24, 'Понять назначение индивидуального оснащения и безопасные правила обращения со стерильными материалами.', 'Знать не только наличие средства, но и его назначение, срок годности и актуальную инструкцию.', 'Проверить → выбрать по назначению → сохранить стерильность → применить по инструкции → пополнить.', 'Составьте собственный чек-лист проверки аптечки без записи служебных сведений.'),
  ('21000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000001', 'Первичная оценка и вызов помощи', 4, true, 'Теория + тест + развернутый ответ', 42, 'Освоить безопасную общую последовательность первичной оценки пострадавшего до передачи медицинским специалистам.', 'Собственная безопасность и устранение непосредственной угрозы предшествуют контакту с пострадавшим.', 'Безопасность → сознание и дыхание → вызов помощи → критические состояния → наблюдение.', 'Проговорите алгоритм вслух, не добавляя несуществующие условия сценария.'),
  ('21000000-0000-4000-8000-000000000005', '10000000-0000-4000-8000-000000000001', 'Наружное кровотечение', 5, true, 'Теория + тест', 28, 'Распознавать опасное наружное кровотечение и выбирать допустимый способ временной остановки в пределах подготовки.', 'Сначала самый простой эффективный способ; более сложные средства — по показаниям и после обучения.', 'Распознать → прямое давление → повязка → специальное средство при показаниях → контроль.', 'Практические навыки остановки кровотечения должны отрабатываться очно на тренажере.'),
  ('21000000-0000-4000-8000-000000000006', '10000000-0000-4000-8000-000000000001', 'Раны и перевязочные материалы', 6, true, 'Теория + тест', 25, 'Безопасно закрывать рану перевязочным материалом и контролировать состояние после наложения повязки.', 'Повязка защищает рану, но не должна создавать новое нарушение кровообращения.', 'Не загрязнять → закрыть → закрепить → проверить кровообращение и состояние.', 'Отрабатывайте наложение повязок очно; текст помогает понять критерии правильности, но не заменяет навык.'),
  ('21000000-0000-4000-8000-000000000007', '10000000-0000-4000-8000-000000000001', 'Наблюдение и передача пострадавшего', 7, true, 'Теория + тест + развернутый ответ', 38, 'Поддерживать непрерывный контроль состояния и передавать медицинским специалистам значимые сведения.', 'Первая помощь не заканчивается после одного действия — состояние контролируют до передачи специалистам.', 'Повторная оценка → защита от температуры → психологическая поддержка → точная передача.', 'Стройте передачу информации по схеме: что произошло, что обнаружено, что сделано, что изменилось.'),
  ('21000000-0000-4000-8000-000000000008', '10000000-0000-4000-8000-000000000001', 'Итоговая медицинская проверка', 8, true, 'Итоговый тест', 22, 'Связать профилактику, первичную оценку, остановку кровотечения и передачу пострадавшего в единый безопасный порядок.', 'Правильное действие определяется состоянием, безопасностью и пределами подготовки.', 'Не угадывать диагноз — распознавать угрозы жизни и действовать по проверенному порядку.', 'Перед тестом восстановите общий алгоритм без подсказки.'),
  ('22000000-0000-4000-8000-000000000001', '10000000-0000-4000-8000-000000000002', 'Меры безопасности', 1, true, 'Теория + тест', 25, null, null, null, null),
  ('22000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000000002', 'Основы устройства', 2, true, 'Теория + тест', 25, null, null, null, null),
  ('22000000-0000-4000-8000-000000000003', '10000000-0000-4000-8000-000000000002', 'Подготовка к применению', 3, true, 'Теория + тест', 25, null, null, null, null),
  ('22000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000002', 'Положения', 4, true, 'Теория + тест', 25, null, null, null, null),
  ('22000000-0000-4000-8000-000000000005', '10000000-0000-4000-8000-000000000002', 'Практические сценарии', 5, true, 'Теория + тест', 25, null, null, null, null),
  ('22000000-0000-4000-8000-000000000006', '10000000-0000-4000-8000-000000000002', 'Контроль знаний', 6, true, 'Итоговый тест', 25, null, null, null, null),
  ('23000000-0000-4000-8000-000000000001', '10000000-0000-4000-8000-000000000003', 'РХБ-угрозы и поражающие факторы', 1, true, 'Теория + тест', 28, 'Различать радиационную, химическую и биологическую опасность по характеру воздействия и способу контроля.', 'Тип угрозы определяет способ обнаружения, защиты и обработки.', 'Радиация измеряется приборами; химическая и биологическая опасность может не иметь очевидных признаков.', 'Сравнивайте угрозы по четырем признакам: источник, путь воздействия, обнаружение, защита.'),
  ('23000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000000003', 'Индивидуальная и коллективная защита', 2, true, 'Теория + тест', 30, 'Понимать назначение средств защиты органов дыхания, кожи, глаз и коллективных защитных объектов.', 'Средство защищает только при правильном подборе, исправности и соблюдении режима использования.', 'Подобрать → проверить → применить по команде и инструкции → контролировать состояние.', 'Практическую проверку герметичности и надевание выполняйте только по программе очных занятий.'),
  ('23000000-0000-4000-8000-000000000003', '10000000-0000-4000-8000-000000000003', 'Радиационный и химический контроль', 3, true, 'Теория + тест + развернутый ответ', 40, 'Различать обнаружение, измерение мощности дозы, учет накопленной дозы и химическую индикацию.', 'Показание прибора имеет смысл только вместе с единицей, режимом, временем и условиями измерения.', 'Обнаружить → измерить → зафиксировать → сообщить → действовать по установленному решению.', 'Не запоминайте кнопки устаревающих моделей: сначала поймите назначение класса приборов.'),
  ('23000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000003', 'Заражение и специальная обработка', 4, true, 'Теория + тест', 29, 'Различать дезактивацию, дегазацию и дезинфекцию, а также частичную и полную специальную обработку.', 'Не переносить загрязнение с зараженной поверхности на чистую зону, кожу или средства защиты.', 'Ограничить контакт → обозначить загрязнение → частичная обработка → контроль → полная обработка.', 'Запомните объект каждого термина: радиоактивные вещества, токсичные химикаты, биологические агенты.'),
  ('23000000-0000-4000-8000-000000000005', '10000000-0000-4000-8000-000000000003', 'Действия при РХБ-опасности', 5, true, 'Итоговый тест', 26, 'Объединить оповещение, применение защиты, ограничение контакта, контроль и доклад в единый защитный алгоритм.', 'Сигнал запускает заранее изученный порядок, а не самостоятельный эксперимент с опасной средой.', 'Принять сигнал → применить защиту → укрыться или покинуть зону по указанию → контролировать → доложить.', 'Конкретные сигналы и команды отрабатываются по действующим документам вашей организации, не записывайте их в приложение.'),
  ('24000000-0000-4000-8000-000000000001', '10000000-0000-4000-8000-000000000004', 'Основы тактики', 1, true, 'Теория + тест', 25, null, null, null, null),
  ('24000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000000004', 'Наблюдение', 2, true, 'Теория + тест', 25, null, null, null, null),
  ('24000000-0000-4000-8000-000000000003', '10000000-0000-4000-8000-000000000004', 'Передвижение', 3, true, 'Теория + тест', 25, null, null, null, null),
  ('24000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000004', 'Взаимодействие', 4, true, 'Теория + тест', 25, null, null, null, null),
  ('24000000-0000-4000-8000-000000000005', '10000000-0000-4000-8000-000000000004', 'Организация действий', 5, true, 'Теория + тест', 25, null, null, null, null),
  ('24000000-0000-4000-8000-000000000006', '10000000-0000-4000-8000-000000000004', 'Сценарии', 6, true, 'Теория + тест', 25, null, null, null, null),
  ('24000000-0000-4000-8000-000000000007', '10000000-0000-4000-8000-000000000004', 'Итоговый тест', 7, true, 'Итоговый тест', 25, null, null, null, null),
  ('25000000-0000-4000-8000-000000000001', '10000000-0000-4000-8000-000000000005', 'Топографическая карта и масштаб', 1, true, 'Теория + тест', 26, 'Понимать назначение карты, численный масштаб и номенклатуру листов.', 'Масштаб связывает измерение на карте с соответствующим расстоянием на местности.', 'Прочитать рамку → определить масштаб → оценить точность → выбрать способ измерения.', 'Перед расчетом всегда выписывайте единицы измерения.'),
  ('25000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000000005', 'Условные знаки и рельеф', 2, true, 'Теория + тест', 28, 'Различать масштабные, внемасштабные и пояснительные знаки и читать основные формы рельефа.', 'Знак читают вместе с подписью, цветом, масштабом и окружающими объектами.', 'Тип знака → положение объекта → количественная характеристика → связь с рельефом.', 'Выберите участок карты и объясните назначение каждого встретившегося типа знака.'),
  ('25000000-0000-4000-8000-000000000003', '10000000-0000-4000-8000-000000000005', 'Системы координат', 3, true, 'Теория + тест', 30, 'Различать географические, плоские прямоугольные, полярные и биполярные координаты.', 'Координата имеет смысл только вместе с названием системы и исходными данными.', 'Выбрать систему → определить начало и оси → записать значения и единицы → проверить.', 'Для каждой системы назовите начало координат и величины, задающие точку.'),
  ('25000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000005', 'Ориентирование и направления', 4, true, 'Теория + тест + развернутый ответ', 42, 'Понимать ориентирование карты, выбор ориентиров и различия между истинным, магнитным и сеточным направлениями.', 'Сначала уточняется север и исходное направление, затем определяется положение объектов.', 'Определить север → ориентировать карту → сопоставить ориентиры → уточнить свое положение.', 'Не смешивайте истинный азимут, магнитный азимут и дирекционный угол.'),
  ('25000000-0000-4000-8000-000000000005', '10000000-0000-4000-8000-000000000005', 'Измерение расстояний и площадей', 5, true, 'Теория + тест', 30, 'Выбирать способ измерения по карте и оценивать точность результата.', 'Результат измерения всегда сопровождается единицей и оценкой погрешности.', 'Измерить на карте → применить масштаб → учесть кривизну и рельеф → проверить единицы.', 'Сделайте обратную проверку: переведите результат обратно в длину на карте.'),
  ('25000000-0000-4000-8000-000000000006', '10000000-0000-4000-8000-000000000005', 'Подготовка и ведение рабочей карты', 6, true, 'Теория + тест + развернутый ответ', 40, 'Подготавливать карту к работе и наносить только необходимые, читаемые и привязанные ко времени данные.', 'Рабочая карта помогает решению задачи только пока остается точной, актуальной и читаемой.', 'Ознакомить → склеить и сложить → выделить основу → наносить данные → обновлять.', 'В учебном приложении используйте только вымышленные схемы и никогда не вводите реальные служебные данные.'),
  ('25000000-0000-4000-8000-000000000007', '10000000-0000-4000-8000-000000000005', 'Итоговая топографическая проверка', 7, true, 'Итоговый тест', 24, 'Связать чтение карты, координаты, ориентирование и измерения в единый проверяемый процесс.', 'Любой результат должен быть воспроизводим по указанным исходным данным.', 'Система → исходные данные → измерение → единицы → независимая проверка.', 'Ищите не только правильный результат, но и достаточность исходных данных.'),
  ('26000000-0000-4000-8000-000000000001', '10000000-0000-4000-8000-000000000006', 'Общие положения', 1, true, 'Теория + тест', 25, null, null, null, null),
  ('26000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000000006', 'Инженерные средства', 2, true, 'Теория + тест', 25, null, null, null, null),
  ('26000000-0000-4000-8000-000000000003', '10000000-0000-4000-8000-000000000006', 'Оборудование позиций', 3, true, 'Теория + тест', 25, null, null, null, null),
  ('26000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000006', 'Итоговый тест', 4, true, 'Итоговый тест', 25, null, null, null, null),
  ('27000000-0000-4000-8000-000000000001', '10000000-0000-4000-8000-000000000007', 'Внутренняя служба и общие обязанности', 1, true, 'Теория + тест', 28, 'Понимать назначение внутренней службы и основу общих обязанностей военнослужащего.', 'Требования внутренней службы обязательны и направлены на порядок, дисциплину, безопасность и готовность.', 'Знать требования → исполнять обязанности → соблюдать безопасность → отвечать за свои действия.', 'Для правовых вопросов всегда сверяйте формулировку с актуальной официальной редакцией.'),
  ('27000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000000007', 'Взаимоотношения и исполнение приказа', 2, true, 'Теория + тест + развернутый ответ', 42, 'Различать начальников и подчиненных, понимать структуру приказа и порядок уточнения неясной задачи.', 'Приказ должен быть понят, точно и своевременно исполнен; неясность уточняется установленным порядком.', 'Выслушать → уяснить → при необходимости уточнить → исполнить → доложить.', 'Не переносите в учебный ответ реальные приказы, фамилии и сведения о задачах.'),
  ('27000000-0000-4000-8000-000000000003', '10000000-0000-4000-8000-000000000007', 'Внутренний порядок и суточный наряд', 3, true, 'Теория + тест', 30, 'Понимать назначение распорядка времени, внутреннего порядка и общие принципы суточного наряда.', 'Перед заступлением обязанности изучаются по актуальной инструкции конкретного наряда.', 'Назначение → подготовка → инструктаж → несение службы → смена и доклад.', 'Учебный модуль дает основу; конкретные обязанности всегда берутся из действующей инструкции.'),
  ('27000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000007', 'Воинская дисциплина и обращения', 4, true, 'Теория + тест + развернутый ответ', 40, 'Понимать сущность дисциплины, личную ответственность и общий порядок предложений, заявлений и жалоб.', 'Дисциплина основана на осознанном исполнении закона, уставов и приказов, а не только на взыскании.', 'Знать требования → исполнять → предотвращать нарушения → сообщать и обращаться по установленному порядку.', 'Не заучивайте перечни взысканий из старого файла — работайте с актуальной официальной редакцией.'),
  ('27000000-0000-4000-8000-000000000005', '10000000-0000-4000-8000-000000000007', 'Караульная служба и строевые понятия', 5, true, 'Итоговый тест', 30, 'Знать назначение караульной службы и базовые строевые термины без подмены очной практической подготовки.', 'Специальные обязанности и практические приемы выполняются только после подготовки по актуальным документам.', 'Охрана и оборона объектов; строй, шеренга, фланг, фронт, интервал, дистанция и команда.', 'Определения можно изучить онлайн, а приемы и обязанности караула — только очно и по действующей инструкции.');
insert into public.learning_activities (id, module_id, type, title, description, position, estimated_minutes, prompt, instructions, hint, max_length, is_published)
