  ('612ff91e-46a6-4cdb-bfbe-86497631a20c', '26000000-0000-4000-8000-000000000002', 'quiz'::public.activity_type, 'Проверка знаний', 'Тест по теме «Инженерные средства»', 2, 9, null, null, 'Ответьте на все вопросы перед отправкой.', null, true),
  ('93b8c884-9701-4955-831a-c76374b32126', '26000000-0000-4000-8000-000000000003', 'theory'::public.activity_type, 'Теория', 'Теоретический материал', 1, 14, null, null, null, null, true),
  ('ac24728d-d436-4b6d-8933-23d6468125d9', '26000000-0000-4000-8000-000000000003', 'quiz'::public.activity_type, 'Проверка знаний', 'Тест по теме «Оборудование позиций»', 2, 9, null, null, 'Ответьте на все вопросы перед отправкой.', null, true),
  ('19f656a5-62f3-4dc5-a041-f1f181ced825', '26000000-0000-4000-8000-000000000004', 'theory'::public.activity_type, 'Теория', 'Теоретический материал', 1, 14, null, null, null, null, true),
  ('5e37d25c-d340-49d1-abd4-6f644c720f58', '26000000-0000-4000-8000-000000000004', 'quiz'::public.activity_type, 'Итоговая проверка', 'Тест по теме «Итоговый тест»', 2, 9, null, null, 'Ответьте на все вопросы перед отправкой.', null, true),
  ('22c44d63-aa40-4f90-b66d-2afd980c6b7e', '27000000-0000-4000-8000-000000000001', 'theory'::public.activity_type, 'Теория', 'Теоретический материал', 1, 15, null, null, null, null, true),
  ('76bdeebc-840d-42d7-b480-10c981f1407d', '27000000-0000-4000-8000-000000000001', 'quiz'::public.activity_type, 'Проверка знаний', 'Тест по теме «Внутренняя служба и общие обязанности»', 2, 10, null, null, 'Ответьте на все вопросы перед отправкой.', null, true),
  ('d6b86eb7-b52e-4cf2-8c87-80f117cf7bc6', '27000000-0000-4000-8000-000000000002', 'theory'::public.activity_type, 'Теория', 'Теоретический материал', 1, 23, null, null, null, null, true),
  ('33ea6068-ed1e-4b64-84e3-a8b9d8c68cc8', '27000000-0000-4000-8000-000000000002', 'quiz'::public.activity_type, 'Проверка знаний', 'Тест по теме «Взаимоотношения и исполнение приказа»', 2, 15, null, null, 'Ответьте на все вопросы перед отправкой.', null, true),
  ('ccefc69b-5c78-43cc-bc7c-eca5bc552e42', '27000000-0000-4000-8000-000000000002', 'free_answer'::public.activity_type, 'Развернутый ответ', 'Проверка понимания и последовательности рассуждения', 3, 12, 'Опишите обезличенный порядок работы с полученным приказом: от восприятия до доклада. Что делать, если задача неясна?', 'Ответьте своими словами. Не указывайте подразделение, место службы, ВУС и иные служебные сведения. Оцениваются только положения изученного материала.', null, 2400, true),
  ('31b9b0d5-fea5-43aa-a0da-d2d86e177d4b', '27000000-0000-4000-8000-000000000003', 'theory'::public.activity_type, 'Теория', 'Теоретический материал', 1, 17, null, null, null, null, true),
  ('a3892467-8910-4b9a-974f-fb829426d726', '27000000-0000-4000-8000-000000000003', 'quiz'::public.activity_type, 'Проверка знаний', 'Тест по теме «Внутренний порядок и суточный наряд»', 2, 11, null, null, 'Ответьте на все вопросы перед отправкой.', null, true),
  ('58556a7b-bc21-42dd-b55e-0df4562b2e32', '27000000-0000-4000-8000-000000000004', 'theory'::public.activity_type, 'Теория', 'Теоретический материал', 1, 22, null, null, null, null, true),
  ('cb07bfb7-5b88-4ed9-89da-099f9837cc0b', '27000000-0000-4000-8000-000000000004', 'quiz'::public.activity_type, 'Проверка знаний', 'Тест по теме «Воинская дисциплина и обращения»', 2, 14, null, null, 'Ответьте на все вопросы перед отправкой.', null, true),
  ('39d06fdf-a3b7-47eb-bd20-f41c08bd120e', '27000000-0000-4000-8000-000000000004', 'free_answer'::public.activity_type, 'Развернутый ответ', 'Проверка понимания и последовательности рассуждения', 3, 12, 'Объясните, из каких элементов складывается воинская дисциплина и как должен быть построен корректный обезличенный рапорт или обращение по проблемной ситуации.', 'Ответьте своими словами. Не указывайте подразделение, место службы, ВУС и иные служебные сведения. Оцениваются только положения изученного материала.', null, 2400, true),
  ('46aa7a81-9456-4438-8fd2-19af3a5fc33d', '27000000-0000-4000-8000-000000000005', 'theory'::public.activity_type, 'Теория', 'Теоретический материал', 1, 17, null, null, null, null, true),
  ('3b68e59f-c59c-49e6-b14c-c116f4971a06', '27000000-0000-4000-8000-000000000005', 'quiz'::public.activity_type, 'Итоговая проверка', 'Тест по теме «Караульная служба и строевые понятия»', 2, 11, null, null, 'Ответьте на все вопросы перед отправкой.', null, true);
insert into public.module_sections (id, module_id, title, body, position)
values
  ('65359a47-9557-4019-b0ae-38a9f7d2de0c', '21000000-0000-4000-8000-000000000001', '1. Источник и пути передачи', 'Инфекционное заболевание вызывается возбудителем. Источником может быть заболевший человек, носитель или зараженный объект окружающей среды. Основные пути передачи — воздушный, водный, пищевой, контактно-бытовой и трансмиссивный. Профилактика эффективна, когда она разрывает конкретное звено этой цепочки, а не ограничивается общей осторожностью.', 1),
  ('fd678a0d-b2de-4cd1-9bc4-4ace41b993d2', '21000000-0000-4000-8000-000000000001', '2. Личная профилактика', 'Поддерживайте чистоту рук, тела, одежды и обуви; используйте только безопасную воду и пищу; защищайтесь от насекомых и клещей; не пользуйтесь общими предметами личной гигиены. При признаках заболевания не скрывайте состояние, ограничьте ненужные контакты и своевременно доложите установленным порядком для получения медицинской помощи.', 2),
  ('08668371-bcb1-4984-8c33-fa7f0baa09ee', '21000000-0000-4000-8000-000000000002', '1. Вода и пункты снабжения', 'Пункт водоснабжения предназначен для добычи, очистки, хранения и выдачи воды; водоразборный пункт — прежде всего для выдачи запасов. Для питья и приготовления пищи используют воду из разрешенного источника, прошедшую установленную обработку. Прозрачность, отсутствие запаха и приятный вкус сами по себе не гарантируют эпидемиологическую безопасность.', 1),
  ('e0b4ff77-ac40-4610-afa1-892dc89bdf4a', '21000000-0000-4000-8000-000000000002', '2. Питание и хранение', 'Руки, посуда и тара должны оставаться чистыми, сырые и готовые продукты — храниться раздельно, а сроки и температурный режим — соблюдаться. Пищу или воду с неизвестным происхождением, нарушенной упаковкой либо признаками порчи не используют до проверки ответственными специалистами. Индивидуальные средства обеззараживания применяют только по актуальной инструкции к конкретному средству.', 2),
  ('957337bd-0588-4595-88c8-c129b67b19aa', '21000000-0000-4000-8000-000000000003', '1. Проверка готовности', 'Перед использованием важно знать фактическую комплектацию выданного набора, расположение предметов, целостность упаковки и сроки годности. Универсального состава на все периоды и условия нет: сведения из старых пособий не заменяют действующую комплектовочную ведомость, обучение и инструкцию производителя.', 1),
  ('0d25166a-a078-4f05-9160-7ff8561fb404', '21000000-0000-4000-8000-000000000003', '2. Стерильные материалы', 'Перевязочный пакет используют для защиты раны и фиксации повязки. При раскрытии не касаются руками поверхности подушечки, которая будет прилегать к ране. После применения израсходованные или поврежденные средства подлежат учету и пополнению установленным порядком. Медикаменты и инъекционные средства не применяют только по памяти из учебного текста.', 2),
  ('ce977bfa-6b32-4241-b4f5-7bd38769c66c', '21000000-0000-4000-8000-000000000004', '1. Безопасность и первичные признаки', 'Оцените угрозы для себя, пострадавшего и окружающих и по возможности прекратите действие повреждающего фактора. Затем проверьте наличие сознания и дыхания доступным безопасным способом. Если состояние угрожает жизни, организуйте вызов экстренной медицинской помощи и привлеките окружающих, действуя в пределах своей подготовки.', 1),
  ('61820c8c-4b6d-4307-9553-60b0183a801e', '21000000-0000-4000-8000-000000000004', '2. Приоритет и наблюдение', 'После первичной оценки приоритет получают состояния, непосредственно угрожающие жизни, включая отсутствие нормального дыхания и массивное наружное кровотечение. После выполненных мероприятий повторно контролируют сознание, дыхание и кровотечение, защищают пострадавшего от переохлаждения или перегревания и передают специалистам сведения о состоянии и сделанных действиях.', 2),
  ('68e7679c-5b5b-4b80-9c0a-7fb0f8b4fbe5', '21000000-0000-4000-8000-000000000005', '1. Приоритет кровотечения', 'Признаки массивного наружного кровотечения требуют немедленной реакции. Используйте средства барьерной защиты, если они доступны, обеспечьте прямое давление на рану и организуйте вызов помощи. Давящая повязка поддерживает давление, когда это соответствует характеру повреждения.', 1),
  ('77386a25-92ef-41a8-ae68-6f87927108c2', '21000000-0000-4000-8000-000000000005', '2. Специальные средства и контроль', 'Кровоостанавливающий жгут применяют при угрожающем жизни кровотечении из конечности, когда это необходимо и навык отработан. После наложения фиксируют время по действующему порядку, не скрывают средство под одеждой и регулярно контролируют кровотечение и состояние пострадавшего до передачи специалистам. Не извлекают глубоко находящиеся инородные предметы из раны.', 2),
  ('4ce35a7e-61c3-4c34-a5ef-39d9adc3200c', '21000000-0000-4000-8000-000000000006', '1. Наложение повязки', 'По возможности используйте стерильный материал и не касайтесь его контактной поверхности. Рану закрывают полностью, материал закрепляют без смещения. Инородный предмет, фиксированный в ране, самостоятельно не извлекают: повязку располагают вокруг него и ожидают медицинскую помощь.', 1),
  ('6df43326-9373-4258-9f5b-28c41edfefaa', '21000000-0000-4000-8000-000000000006', '2. Проверка после наложения', 'После фиксации оценивают, не усилилось ли кровотечение, не появились ли на участке ниже повязки нарастающая боль, онемение, похолодание или изменение цвета. При ухудшении корректируют повязку в пределах навыка и продолжают наблюдение. Практические повязки на сложные области тела требуют очной подготовки.', 2),
  ('b7663320-b9a7-4b61-873c-62556532be52', '21000000-0000-4000-8000-000000000007', '1. Повторная оценка', 'Регулярно контролируйте сознание, дыхание, наружное кровотечение и общее изменение состояния. Не давайте пострадавшему пищу, воду или препараты без установленных оснований. Защищайте от переохлаждения и перегревания, поддерживайте спокойный контакт и не оставляйте без наблюдения, если состояние нестабильно.', 1),
  ('4bd4b342-4929-4875-868e-7ff669cb27dd', '21000000-0000-4000-8000-000000000007', '2. Передача информации', 'При передаче сообщите, что произошло по известным данным, какие признаки были обнаружены, какие мероприятия выполнены и когда, как изменялось состояние. Отделяйте факты от предположений: не ставьте диагноз и прямо обозначайте неизвестные сведения.', 2),
  ('d43eaa43-e861-40ee-ac31-74edbaa09ce8', '21000000-0000-4000-8000-000000000008', '1. Что нужно объединить', 'Профилактические меры уменьшают вероятность заболевания, а первая помощь начинается после происшествия с безопасности и первичной оценки. Индивидуальное оснащение эффективно только при исправности, правильном выборе средства и отработанном навыке. Любое действие завершается повторным контролем.', 1),
  ('981a192f-37b7-4931-8a05-0218b0bca870', '21000000-0000-4000-8000-000000000008', '2. Границы курса', 'Курс не заменяет очную практику, медицинскую консультацию, действующие приказы и инструкции к конкретным средствам. При расхождении старого пособия с актуальным официальным порядком применяется действующий порядок. Итог тестирует понимание логики, а не право выполнять медицинские вмешательства вне своей подготовки.', 2),
  ('3d96a991-baa8-4af5-b466-3d7786d7bd5e', '23000000-0000-4000-8000-000000000001', '1. Три группы опасностей', 'Радиационная опасность связана с ионизирующим излучением и радиоактивным загрязнением. Химическая — с токсичными химическими веществами и заражением воздуха, местности или предметов. Биологическая — с патогенными микроорганизмами, токсинами и возможностью распространения через воздух, воду, пищу, контакт или переносчиков.', 1),
  ('231c3dc2-aa74-469a-8239-99cb6ded28a4', '23000000-0000-4000-8000-000000000001', '2. Почему нельзя полагаться на органы чувств', 'Отсутствие запаха, дыма или видимых следов не подтверждает безопасность. Для обнаружения и оценки применяют установленные средства контроля, наблюдение и официальные сообщения. Самостоятельный контакт с подозрительным веществом или предметом для проверки недопустим.', 2),
  ('1ff7a331-5d1c-4715-8a71-9c9807f7fdb2', '23000000-0000-4000-8000-000000000002', '1. Средства индивидуальной защиты', 'Средства защиты органов дыхания уменьшают поступление опасных аэрозолей, паров или газов в пределах своего назначения. Средства защиты кожи и глаз снижают контакт с зараженной средой. Универсального средства для всех угроз нет; важны назначение, размер, исправность, герметичность и ограничения по времени и нагрузке.', 1),
  ('fe3be33f-017e-4b55-beea-660f37b65e17', '23000000-0000-4000-8000-000000000002', '2. Коллективная защита', 'Коллективная защита создается оборудованными сооружениями и системами очистки или изоляции воздуха. Ее эффективность зависит от герметичности, исправности фильтровентиляционного оборудования и соблюдения установленного режима входа, выхода и эксплуатации. Самовольное изменение режима может нарушить защиту всех находящихся внутри.', 2),
  ('6c8fedb8-9848-4ae1-85d7-3020c22ae1f3', '23000000-0000-4000-8000-000000000003', '1. Назначение контроля', 'Индикатор сообщает о наличии или изменении опасного фактора, измеритель мощности дозы характеризует интенсивность излучения в момент и месте измерения, а индивидуальный дозиметр помогает учитывать накопленную дозу. Эти величины нельзя подменять друг другом.', 1),
  ('9a851a33-ab4f-4205-b8ac-c121e55ddcd8', '23000000-0000-4000-8000-000000000003', '2. Достоверность результата', 'Перед работой проверяют комплектность, питание, исходное состояние и выбранный режим согласно инструкции конкретного прибора. Результат фиксируют вместе с единицей измерения, временем и местом без раскрытия в учебном приложении служебных координат. Необычное показание перепроверяют установленным способом и немедленно докладывают.', 2),
  ('f8ec1855-30e6-4749-a935-2bdc70d2ac49', '23000000-0000-4000-8000-000000000004', '1. Три вида обеззараживания', 'Дезактивация направлена на удаление радиоактивных веществ, дегазация — на удаление или обезвреживание токсичных химических веществ, дезинфекция — на уничтожение или безопасное снижение количества биологических возбудителей во внешней среде. Конкретные растворы и режимы выбирают только по действующей инструкции.', 1),
  ('2f350202-0b34-4539-89df-cd53b5eb5cd3', '23000000-0000-4000-8000-000000000004', '2. Частичная и полная обработка', 'Частичная специальная обработка выполняется в ограниченном объеме, когда требуется быстро снизить опасность на открытых участках, средствах защиты или критичных поверхностях. Полная обработка проводится организованно, установленными силами и средствами, с контролем результата. Снятие защиты без учета загрязнения может привести к вторичному поражению.', 2),
  ('7c931ed8-98db-471e-98a7-010ed4b85707', '23000000-0000-4000-8000-000000000005', '1. Общая последовательность', 'После официального сигнала или обнаружения признаков опасности применяют положенные средства защиты, выполняют установленную команду по укрытию или выходу из зоны, минимизируют контакт с поверхностями и не принимают пищу или воду из сомнительных источников. Действия выполняются без самовольного снятия защиты.', 1),
  ('63113112-eebd-4cde-9be6-71447f662d17', '23000000-0000-4000-8000-000000000005', '2. Контроль и доклад', 'Факты наблюдения, показания средств контроля и выполненные меры передают установленным порядком. В учебное приложение нельзя вводить реальные координаты, состав подразделения и иные служебные сведения. Снятие ограничений и средств защиты выполняется только после соответствующего указания и контроля.', 2),
  ('b3dd72c6-85da-4b34-8d0d-7028f792bba8', '25000000-0000-4000-8000-000000000001', '1. Карта и ее характеристики', 'Топографическая карта — уменьшенное, обобщенное и условно-знаковое изображение местности. При знакомстве с листом оценивают масштаб, год съемки или обновления, систему координат, высоту сечения рельефа и зарамочное оформление. Эти сведения определяют допустимую точность последующей работы.', 1),
  ('c1d4438a-69e1-4690-8207-02f249eef263', '25000000-0000-4000-8000-000000000001', '2. Масштаб и номенклатура', 'Численный масштаб 1:N означает, что одной единице длины на карте соответствуют N таких же единиц на местности. Чем меньше знаменатель, тем крупнее масштаб и подробнее изображение. Номенклатура однозначно обозначает лист карты и строится по установленной системе разграфки.', 2),
  ('1f9e21df-27cf-41e5-b854-5e096390dd2b', '25000000-0000-4000-8000-000000000002', '1. Виды условных знаков', 'Масштабные знаки показывают объекты, размеры которых можно выразить в масштабе карты. Внемасштабные обозначают малые объекты, положение которых определяется главной точкой знака. Пояснительные знаки и подписи дополняют характеристику объекта: породу леса, ширину дороги, глубину и другие свойства.', 1),
  ('a0a274d4-04f3-4e02-aa2d-97984484d375', '25000000-0000-4000-8000-000000000002', '2. Изображение рельефа', 'Рельеф изображают горизонталями — линиями равной абсолютной высоты. Чем ближе горизонтали друг к другу, тем круче склон. Бергштрихи и отметки высот помогают определить направление понижения, вершины, котловины, хребты, лощины и седловины.', 2),
  ('be01b9ce-7377-4013-997f-d744823cc6b1', '25000000-0000-4000-8000-000000000003', '1. Географические и прямоугольные координаты', 'Географические координаты задают положение угловыми величинами — широтой и долготой — относительно экватора и начального меридиана. Плоские прямоугольные координаты задают линейное положение точки в координатной зоне по осям X и Y и удобны для измерений и расчетов на топографической карте.', 1),
  ('77cb4668-fc2e-4f62-a283-500a261e9b94', '25000000-0000-4000-8000-000000000003', '2. Полярные и биполярные координаты', 'В полярной системе точку определяют направлением от выбранной полярной оси и расстоянием от полюса. В биполярной системе используют измерения от двух известных точек и общей базы. Эти системы локальны: при передаче данных необходимо явно указывать исходные точки и направление отсчета.', 2),
  ('83fe0627-0ba3-40a2-a384-4303df575218', '25000000-0000-4000-8000-000000000004', '1. Сущность ориентирования', 'Ориентироваться на местности — значит определить стороны горизонта, свое положение относительно окружающих объектов и нужное направление движения. Карту ориентируют так, чтобы направления на ней были параллельны соответствующим направлениям на местности, после чего сличают заметные и устойчивые ориентиры.', 1),
  ('939ec3eb-17e1-4b46-87da-b62c1a91de72', '25000000-0000-4000-8000-000000000004', '2. Исходные направления', 'Истинный меридиан направлен к географическому северу, магнитный — по направлению магнитной стрелки, вертикальная линия координатной сетки задает сеточное направление. Углы между этими направлениями учитывают по зарамочному оформлению актуальной карты. Магнитные способы чувствительны к металлу, электропроводам и локальным аномалиям.', 2),
  ('c7c7053c-9aab-43f5-96fd-3bc68de49d2d', '25000000-0000-4000-8000-000000000005', '1. Прямые и извилистые линии', 'Прямой отрезок измеряют линейкой или циркулем и переводят по масштабу. Извилистую линию разбивают на короткие участки, используют курвиметр или шаг раствора циркуля. Чем подробнее повторяется изгиб, тем точнее результат, но итог все равно ограничен точностью карты.', 1),
  ('5037805c-2be4-4d38-bddc-fa18df6c236c', '25000000-0000-4000-8000-000000000005', '2. Площадь и погрешность', 'Площадь можно оценивать по квадратам координатной сетки или разбиением контура на простые фигуры. Ошибки возникают из-за толщины линий, обобщения карты, рельефа, выбора точек и округления. Измеренная по карте горизонтальная длина может отличаться от фактического пути по склонам.', 2),
  ('5b75670a-330e-4b2c-a29f-3c32246e6545', '25000000-0000-4000-8000-000000000006', '1. Подготовка карты', 'Подготовка включает ознакомление с характеристиками листов, при необходимости склеивание, правильное складывание и подъем основных объектов. Содержание зарамочного оформления и современность карты проверяют до начала расчетов. Карта должна раскрываться на нужном участке без полного разворачивания.', 1),
  ('75252b19-e9b8-438e-a3a6-ed0325ef9484', '25000000-0000-4000-8000-000000000006', '2. Ведение и читаемость', 'На рабочую карту наносят данные, необходимые для конкретной задачи, соблюдая установленные условные знаки, цвета и отметки времени. Фактическое положение отделяют от предполагаемого различным начертанием. Подписи не должны закрывать высоты, ориентиры и названия. Устаревшие сведения своевременно удаляют или обновляют установленным способом.', 2),
  ('e886f0d6-f3cc-4a31-a20d-71616484ae9d', '25000000-0000-4000-8000-000000000007', '1. Контроль исходных данных', 'Перед решением задачи указывают лист, масштаб, систему координат, исходное направление и единицы. Затем выбирают подходящий способ измерения. Если хотя бы один из этих элементов не определен, числовой ответ может оказаться формально точным, но фактически неверным.', 1),
  ('a80c35a0-e84b-457a-8932-a631779d8082', '25000000-0000-4000-8000-000000000007', '2. Независимая проверка', 'Результат проверяют обратным пересчетом, вторым ориентиром, альтернативным измерением или сопоставлением с рельефом и объектами. В учебных ответах не используют реальные маршруты, координаты или обстановку подразделений — достаточно вымышленных данных.', 2),
  ('52febd75-a929-44ef-9c64-995edfc19c73', '27000000-0000-4000-8000-000000000001', '1. Назначение внутренней службы', 'Внутренняя служба поддерживает внутренний порядок и воинскую дисциплину, обеспечивает готовность, безопасность военной службы, обучение личного состава, организованное выполнение повседневных задач и охрану здоровья. Ее требования должен знать и добросовестно выполнять каждый военнослужащий.', 1),
  ('5ce868e0-ea16-474e-8b29-f0710fe53f12', '27000000-0000-4000-8000-000000000001', '2. Обязанности и ответственность', 'Военнослужащий действует на основе Конституции, федеральных законов, общевоинских уставов и приказов. Он обязан сохранять воинскую честь, совершенствовать подготовку, соблюдать требования безопасности, беречь имущество и поддерживать товарищество. Конкретный объем прав и ответственности определяется актуальным законодательством и статусом выполняемой обязанности.', 2),
  ('f9f3f1b2-2a5b-4e3d-a441-3a54274b3606', '27000000-0000-4000-8000-000000000002', '1. Начальники, старшие и подчиненные', 'Служебные взаимоотношения определяются должностью, воинским званием и установленной подчиненностью. Военнослужащие обязаны соблюдать уважение, достоинство и правила воинской вежливости. Требования не должны подменяться унижением или произвольным обращением.', 1),
  ('7ec3b259-1198-41a9-a703-fecf912567f7', '27000000-0000-4000-8000-000000000002', '2. Работа с приказом', 'Получив приказ, военнослужащий должен его уяснить. Если формулировка непонятна, требуется своевременно обратиться за разъяснением, не искажая содержание и не раскрывая сведения посторонним. После исполнения докладывают о результате установленным порядком. Правовая оценка конкретной ситуации выполняется по актуальному уставу и законодательству, а не по учебной догадке.', 2),
  ('82c1174e-21cf-4124-9fb6-595c2d7fee6e', '27000000-0000-4000-8000-000000000003', '1. Распорядок и внутренний порядок', 'Распределение времени обеспечивает готовность, обучение, обслуживание вооружения и техники, бытовые потребности, отдых и охрану здоровья. Внутренний порядок поддерживается выполнением распорядка, правил размещения, требований пожарной безопасности, сохранностью имущества и ответственностью должностных лиц.', 1),
  ('bffa0140-7886-4217-b877-eafe64da7a61', '27000000-0000-4000-8000-000000000003', '2. Суточный наряд', 'Суточный наряд назначается для поддержания внутреннего порядка, охраны личного состава, объектов и имущества, контроля выполнения распорядка и предупреждения происшествий. До заступления военнослужащий обязан пройти подготовку и инструктаж, знать подчиненность, место службы, порядок связи и свои действия по действующей инструкции.', 2),
  ('7e0bcdd8-7a7b-4013-a00e-dad798d3bfc6', '27000000-0000-4000-8000-000000000004', '1. Сущность дисциплины', 'Воинская дисциплина означает строгое и точное соблюдение порядка и правил, установленных законодательством, общевоинскими уставами и приказами. Она поддерживается личной ответственностью, требовательностью командиров, уважением достоинства военнослужащих, поощрением добросовестной службы и законным применением мер ответственности.', 1),
  ('43e2e873-7642-4875-9030-1774fe54f033', '27000000-0000-4000-8000-000000000004', '2. Обращения и актуальность норм', 'Военнослужащий вправе обращаться с предложениями, заявлениями и жалобами в установленном порядке. Учебный ответ должен описывать общий принцип: адресовать обращение компетентному должностному лицу, излагать факты точно и соблюдать установленный канал. Сроки, полномочия и перечни мер проверяют только по актуальной редакции, поскольку приложенный документ не учитывает изменения 2024–2025 годов.', 2),
  ('c76122c5-8236-4971-90ae-d129addd0932', '27000000-0000-4000-8000-000000000005', '1. Назначение караульной службы', 'Караульная служба предназначена для надежной охраны и обороны установленных объектов и выполнения иных задач, определенных актуальным уставом. Она требует точного соблюдения порядка, подготовки и высокой ответственности. Приложенный файл используется только как структура курса; конкретные права, обязанности и основания применения силы в приложение не переносятся.', 1),
  ('cfdd9c15-d77f-4a51-8bae-1219d96a6ffc', '27000000-0000-4000-8000-000000000005', '2. Основные строевые понятия', 'Строй — установленное размещение военнослужащих и подразделений для совместных действий. Шеренга располагается на одной линии; фланг — правая или левая оконечность; фронт — сторона, в которую обращены лицом; интервал измеряется по фронту, дистанция — в глубину. Команда может иметь предварительную и исполнительную части.', 2);
