insert into public.free_answer_rubrics (activity_id, reference_answer_points)
values
  ('e2073414-be13-4e52-8c56-199c15c4aee2', array['Оценить угрозы и обеспечить безопасные условия.', 'Проверить сознание и нормальное дыхание.', 'Организовать вызов экстренной помощи и привлечь окружающих.', 'Выявить и устранить непосредственные угрозы жизни в пределах подготовки.', 'Наблюдать, защищать от неблагоприятной температуры и передать сведения специалистам.']::text[]),
  ('f4541bdb-991a-4b5e-847c-0876cbde9ac9', array['Известные обстоятельства без домыслов.', 'Обнаруженные признаки и результаты повторной оценки.', 'Выполненные мероприятия и время их выполнения.', 'Изменение состояния до момента передачи.']::text[]),
  ('d01d1f92-4eff-44fc-a5a4-bc3534215665', array['Обнаружение отвечает на вопрос о наличии или изменении фактора.', 'Мощность дозы описывает интенсивность излучения в момент измерения.', 'Накопленная доза относится к суммарному воздействию за период.', 'С показанием фиксируются единица, время, режим и условия измерения.']::text[]),
  ('397e3fde-4d62-4779-ad53-8696aa2393b8', array['Определить исходное направление на север подходящим способом.', 'Повернуть карту до параллельности направлений карты и местности.', 'Опознать не менее двух-трех устойчивых ориентиров.', 'Сопоставить направления и расстояния, учесть рельеф.', 'Учитывать металл, токопроводы и магнитные аномалии.']::text[]),
  ('bd6b9a31-1d3e-4550-b1ba-3510727fe167', array['Ознакомиться с масштабом, современностью, системой координат и зарамочными данными.', 'При необходимости склеить и сложить карту для удобной работы.', 'Выделить основные объекты и наносить только необходимые данные.', 'Разделять фактические и предполагаемые сведения, указывать время.', 'Не закрывать элементы основы и своевременно обновлять устаревшие данные.']::text[]),
  ('ccefc69b-5c78-43cc-bc7c-eca5bc552e42', array['Внимательно выслушать и уяснить задачу.', 'Выделить требуемый результат, сроки и ограничения.', 'При неясности запросить разъяснение установленным порядком.', 'Точно и своевременно исполнить в пределах поставленной задачи.', 'Доложить о результате, не раскрывая сведения посторонним.']::text[]),
  ('39d06fdf-a3b7-47eb-bd20-f41c08bd120e', array['Соблюдение законодательства, уставов и приказов.', 'Личная ответственность и предупреждение нарушений.', 'Уважение достоинства и законность требований.', 'Точное изложение проверяемых фактов.', 'Компетентный адресат и установленный канал обращения.']::text[]);
insert into public.content_sources (id, source_key, subject_id, title, kind, file_name, uri, version_label, published_on, verified_at, is_current_verified, notes)
values
  ('e35a7b47-d86f-4bca-b995-3c4aac8d0fd5', 'medical-user-manual', '10000000-0000-4000-8000-000000000001', 'Военно-медицинская подготовка', 'user_document'::public.content_source_kind, 'Военно-медицинская подготовка_1.doc', null, 'редакция в файле не указана', null, null, false, 'Использованы устойчивые положения о гигиене, воде, перевязочных средствах и наблюдении. Устаревающие сведения о препаратах и комплектации аптечек исключены.'),
  ('662fdbb6-aa01-407e-aadf-89f9307fa818', 'medical-order-760', '10000000-0000-4000-8000-000000000001', 'Приказ Министра обороны Российской Федерации от 09.12.2022 № 760', 'official_legal'::public.content_source_kind, null, 'https://publication.pravo.gov.ru/document/0001202212260017', 'официально опубликован 26.12.2022', '2022-12-26', '2026-08-17', true, 'Использован как специальная правовая основа первой помощи военнослужащим в предусмотренных приказом условиях.'),
  ('b1ad7c4d-7805-42b5-9a89-083f0369d704', 'medical-order-220n', '10000000-0000-4000-8000-000000000001', 'Приказ Минздрава России от 03.05.2024 № 220н', 'official_legal'::public.content_source_kind, null, 'https://publication.pravo.gov.ru/document/0001202405310015', 'действует с 01.09.2024', '2024-05-31', '2026-08-17', true, 'Использован для общей последовательности первой помощи и безопасных границ учебного материала.'),
  ('925fdc8d-e028-45aa-9016-009f10d866c3', 'rhb-manual-2016', '10000000-0000-4000-8000-000000000003', 'Радиационная, химическая и биологическая защита', 'training_manual'::public.content_source_kind, 'РХБЗ.pdf', null, 'учебное пособие, Пенза, 2016', '2016-01-01', null, false, 'Использованы защитные понятия и классификации. Конструкции оружия, наступательное применение и устаревающие характеристики приборов в курс не включены.'),
  ('4d85325c-889e-45eb-a977-fb058151a424', 'topography-user-manual', '10000000-0000-4000-8000-000000000005', 'Военная топография', 'user_document'::public.content_source_kind, 'Военная топография.doc', null, 'редакция в файле не указана', null, null, false, 'Использованы базовые определения карт, условных знаков, координат, ориентирования, измерений и рабочей карты.'),
  ('85423aa4-a451-42bd-b0e7-1dcad9cf5fe3', 'regulations-user-internal', '10000000-0000-4000-8000-000000000007', 'Устав внутренней службы Вооруженных Сил Российской Федерации', 'user_document'::public.content_source_kind, 'Общевоинские уставы_01 Устав внутренней службы ВС РФ.docx', null, 'редакция по 21.02.2019', null, null, false, 'Приложенный текст устарел; использован только для структуры тем и стабильных определений.'),
  ('0955c0a6-bfa9-4678-b669-279a721457c2', 'regulations-user-disciplinary', '10000000-0000-4000-8000-000000000007', 'Дисциплинарный устав Вооруженных Сил Российской Федерации', 'user_document'::public.content_source_kind, 'Общевоинские уставы_02 Дисциплинарный устав ВС РФ.docx', null, 'редакция по 06.05.2020', null, null, false, 'Приложенный текст устарел; перечни поощрений и взысканий не перенесены в учебный банк.'),
  ('ba97c295-bf0a-49ab-b8a6-e8a7e3b9f428', 'regulations-user-guard', '10000000-0000-4000-8000-000000000007', 'Устав гарнизонной и караульной служб Вооруженных Сил Российской Федерации', 'user_document'::public.content_source_kind, 'Общевоинские уставы_03 Устав гарнизонной и караульной служб ВС РФ.docx', null, 'редакция в приложенном файле не является актуальной', null, null, false, 'Использован для структуры вводного модуля без переноса изменяемых полномочий и специальных процедур.'),
  ('d1e2e692-8a33-4717-aa37-e95cd74d9b77', 'regulations-user-drill', '10000000-0000-4000-8000-000000000007', 'Строевой устав Вооруженных Сил Российской Федерации', 'user_document'::public.content_source_kind, 'Общевоинские уставы_04 Строевой устав.docx', null, 'приказ Министра обороны РФ от 11.03.2006 № 111', '2006-03-11', null, false, 'Использованы базовые строевые понятия и устройство команды; практические приемы требуют очного обучения.'),
  ('585a33dc-b9b4-438e-98bc-e1bcaba4edda', 'regulations-official-1495', '10000000-0000-4000-8000-000000000007', 'Указ Президента Российской Федерации от 10.11.2007 № 1495', 'official_legal'::public.content_source_kind, null, 'https://www.kremlin.ru/acts/bank/26528/print', 'официальная сводная редакция с изменениями по 24.06.2025', '2007-11-10', '2026-08-17', true, 'При расхождении с приложенными файлами приоритет имеет официальный актуальный текст.');
